"""Get minimal value of list, version 1.

lst: Numbers list
return: Minimal value and its count on the list
"""
def min_count1(lst: list[int | float]) -> list[int | float] {
    if len(lst) == 0 {
        return [];
    }
    count = 0;
    min_value = lst[0];
    for num in lst {
        if num == min_value {
            count += 1;
        } elif num < min_value {
            count = 1;
            min_value = num;
        }
    }
    return [min_value, count];
}

"""Create an octave-repeating scale from a tonic note and a pattern of intervals.

Args:
    tonic: root note (midi note number)
    pattern: pattern of intervals (semitones)
    octave: span of scale (in octaves)

Returns:
    list of midi notes in the scale
"""
def create_scale(tonic: int, pattern: list[int], octave: int = 1) -> list[int] {
    assert sum(pattern) == 12;
    scale = [tonic];
    note = tonic;
    for o in range(octave) {
        for i in pattern {
            note += i;
            if note <= 127 {
                scale.append(note);
            }
        }
    }
    return scale;
}

"""IOBES -> IOB"""
def iobes_iob(tags: list[str]) -> list[str] {
    new_tags = [];
    for tag in tags {
        if tag == 'rel' {
            new_tags.append(tag);
        } elif tag.split('-')[0] == 'B' {
            new_tags.append(tag);
        } elif tag.split('-')[0] == 'I' {
            new_tags.append(tag);
        } elif tag.split('-')[0] == 'S' {
            new_tags.append(tag.replace('S-', 'B-'));
        } elif tag.split('-')[0] == 'E' {
            new_tags.append(tag.replace('E-', 'I-'));
        } elif tag.split('-')[0] == 'O' {
            new_tags.append(tag);
        } else {
            raise Exception('Invalid format!');
        }
    }
    return new_tags;
}

"""
    Compares two values and returns:
        true when the first value is greater than the second value.
        false when the first value is less than or equivalent to the second value.
    See https://docs.mongodb.com/manual/reference/operator/aggregation/gt/
    for more details
    :param x: first value or expression
    :param y: second value or expression
    :return: Aggregation operator
    """
def GT(x: Any = None, y: Any = None) -> object {
    if ((x is None) and (y is None)) {
        return {'$gt': []};
    }
    return {'$gt': [x, y]};
}

