""" Splits dictionary numbers by the decimal point."""
def splitter(h: Any) -> object {
    if (`type(h) is `dict) {
        for (k, i) in h.items() {
            h[k] = str(i).split('.');
        }
    }
    if (`type(h) is `list) {
        for n in range(0, len(h)) {
            h[n] = splitter(h[n]);
        }
    }
    return h;
}

