def get_counter(data: list[int], base: int) -> tuple[int, int] {
    b0 = data[base];
    b1 = data[base + 1];
    b2 = data[base + 2];
    b3 = data[base + 3];
    counter = b3;
    position = (b1 << 8) + b2;
    return (counter, position);
}

