"""
    Given an index and list of sizes, return a
    name for the layer.

    >>> autoname(0, sizes=4)
    'input'
    >>> autoname(1, sizes=4)
    'hidden1'
    >>> autoname(2, sizes=4)
    'hidden2'
    >>> autoname(3, sizes=4)
    'output'
    """
def autoname(index: int, sizes: int) -> str {
    if index == 0 {
        n = "input";
    } elif index == (sizes - 1) {
        n = "output";
    } elif sizes == 3 {
        n = "hidden";
    } else {
        n = "hidden%d" % index;
    }
    return n;
}

"""Given a class name (aaaUserEp) returns tuple aaa,UserEp"""
def parseMoClassName(className: str) -> tuple[str, str] {
    idx = -1;
    upper_found = False;
    for c in className {
        idx += 1;
        if c.isupper() {
            upper_found = True;
            break;
        }
    }
    if upper_found {
        pkg = className[:idx];
        klass = className[idx:];
    } else {
        pkg = className;
        klass = "";
    }
    return (pkg, klass);
}

