"""Recursively finds fields in script JSON and returns them as a list.
     Field has format: { "field":{ "name":"???", "kind":"???", "default":???, "description":"???" }}

    struct is a dict/list/tuple representation of the JSON script; path
    tracks recursion depth and is not used externally. Returns a list of
    field dicts found in the JSON.
    """
def json_get_fields(struct: dict | list | tuple | str | int | float | bool | None, path: list[str | int] = []) -> list[dict] | dict[str, dict] {
    fields: dict[str, dict] = {};
    path = path[:];
    if isinstance(struct, dict) {
        if 'field' in struct {
            fields[struct['field']['name']] = struct['field'];
        } else {
            for (key, value) in struct.items() {
                fields.update(json_get_fields(value, path + [key]));
            }
        }
    } elif isinstance(struct, list) or isinstance(struct, tuple) {
        for (index, value) in enumerate(struct) {
            fields.update(json_get_fields(value, path + [index]));
        }
    }
    if path == [] {
        return sorted(fields.values(), key=lambda (f: dict) { f.get('order', 0); });
    } else {
        return fields;
    }
}

