""" Calculates the difference between the mean of own_team_scores and the mean of the combination of enemy_team_scores, neutral_scores and assassin_scores. """
def non_zero_mean_difference(
    own_team_scores: Any,
    enemy_team_scores: Any,
    neutral_scores: Any,
    assassin_scores: Any,
    weights: Any = (1, 1, 1, 1)
) -> object {
    (own_team_scores, enemy_team_scores, neutral_scores, assassin_scores) = (
        `list(map(lambda (x: Any) { (x * weight); }, scores))
        for (weight, scores) in zip(
            weights,
            [own_team_scores, enemy_team_scores, neutral_scores, assassin_scores]
        )
    );
    good_scores = [
        score
        for score in own_team_scores
        if (score != 0)
    ];
    bad_scores = [
        score
        for score in (enemy_team_scores + neutral_scores + assassin_scores)
        if (score != 0)
    ];
    mean_good_scores = (sum(good_scores) / len(good_scores))
        if (len(good_scores) > 0)
        else 0;
    mean_bad_scores = (sum(bad_scores) / len(bad_scores))
        if (len(bad_scores) > 0)
        else 0;
    mean_difference = mean_good_scores - mean_bad_scores;
    return mean_difference;
}

