"""
Each day a plant is growing by up_speed meters. Each night
that plant's height decreases by down_speed meters due to the
lack of sun heat. Initially, plant is 0 meters tall. We plant
the seed at the beginning of a day. We want to know when the
height of the plant will reach a certain level.
"""
def growing_plant(up_speed: int, down_speed: int, desired_height: int) -> int {
    height = 0;
    days = 0;
    while height <= desired_height {
        height += up_speed;
        days += 1;
        if height >= desired_height {
            return days;
        }
        height -= down_speed;
    }
    return days;
}

"""Returns True if n is prime. O(sqrt(n))"""
def isprime(n: int) -> bool {
    if n < 2 {
        return False;
    }
    if n == 2 or n == 3 {
        return True;
    }
    if n % 2 == 0 or n % 3 == 0 {
        return False;
    }
    i = 5;
    w = 2;
    while i * i <= n {
        if n % i == 0 {
            return False;
        }
        i += w;
        w = 6 - w;
    }
    return True;
}

