    :returns: bool` of whether the string is binary
    """
def is_binary_string(string_: str | bytes) -> bool {
    if isinstance(string_, str) {
        string_ = bytes(string_, 'utf-8');
    }
    textchars = bytearray(({7, 8, 9, 10, 12, 13, 27} | (set(range(TEXTCHAR_RANGE_START, TEXTCHAR_RANGE_END)) - {DEL_BYTE})));
    return bool(string_.translate(None, textchars));
}

""" 8.4 Power Set: Write a method to return all subsets of a set. """
def power_set(arr: list[int]) -> list[list[int]] {
    if len(arr) == 0 {
        return [[]];
    }
    (head, tail) = (arr[0], arr[1:]);
    tail_subsets = power_set(tail);
    head_subsets = [];
    for sub in tail_subsets {
        new_sub = sub[:];
        new_sub.append(head);
        head_subsets.append(new_sub);
    }
    return tail_subsets + head_subsets;
}

