"""
This solution compresses without checking. Known as the RunLength Compression algorithm.
"""
def compress(s: str) -> str {
    r = "";
    l = len(s);
    if l == 0 {
        return "";
    }
    if l == 1 {
        return s + "1";
    }
    last = s[0];
    cnt = 1;
    i = 1;
    while i < l {
        if s[i] == s[i - 1] {
            cnt += 1;
        } else {
            r = r + s[i - 1] + str(cnt);
            cnt = 1;
        }
        i += 1;
    }
    r = r + s[i - 1] + str(cnt);
    return r;
}

