"""
def _x2n(x: str) -> int {
    numerals = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    b = 26;
    n = 0;
    for (i, l) in enumerate(reversed(x)) {
        n += (numerals.index(l) + 1) * b ** i;
    }
    return n;
}

