    """
def merge_dict(this: Any, other: Any, cb: Any) -> object {
    result = {};
    result.update(this);
    result.update(other);
    for key in (this.keys() & other) {
        ret = cb(this[key], other[key]);
        result[key] = ret;
    }
    return result;
}

