}

glob LIFT_EPSILON = 1e-10;

"""Computes the lift for a rule a -> b based on the contingency table."""
def rule_lift(f11: float, f10: float, f01: float, f00: float) -> float {
    n = f11 + f10 + f01 + f00;
    supp_ab = f11 / n;
    supp_a = f10 / n;
    supp_b = f01 / n;
    return supp_ab / (supp_a * supp_b + LIFT_EPSILON);
}

