"""
    Improvement over binary search when the data is uniformly distributed...
    :param to_be_searched:
    :param searching_for:
    :return:
    """
def interpolation_search(to_be_searched: Any, searching_for: Any) -> object {
    if to_be_searched {
        low = 0;
        high = len(to_be_searched) - 1;
        while (
            (low <= high)
            and (searching_for >= to_be_searched[low])
            and (searching_for <= to_be_searched[high])
        ) {
            pos = (
                low
                + int(
                    (
                        ((searching_for - to_be_searched[low]) * (high - low))
                        / (to_be_searched[high] - to_be_searched[low])
                    )
                )
            );
            if (searching_for == to_be_searched[pos]) {
                return pos;
            }
            if (searching_for < to_be_searched[pos]) {
                high = pos - 1;
            } else {
                low = pos + 1;
            }
        }
    }
    return -1;
}

"""
    This method will transform an integer value into the 0-10 scale string
    representation.

    The scale for this confidence representation is the following:

    .. list-table:: STIX Confidence to 0-10
        :header-rows: 1

        * - Range of Values
          - 0-10 Scale
        * - 0-4
          - 0
        * - 5-14
          - 1
        * - 15-24
          - 2
        * - 25-34
          - 3
        * - 35-44
          - 4
        * - 45-54
          - 5
        * - 55-64
          - 6
        * - 65-74
          - 7
        * - 75-84
          - 8
        * - 95-94
          - 9
        * - 95-100
          - 10

    Args:
        confidence_value (int): An integer value between 0 and 100.

    Returns:
        str: A string corresponding to the 0-10 scale.

    Raises:
        ValueError: If `confidence_value` is out of bounds.

    """
def value_to_zero_ten(confidence_value: Any) -> object {
    if (4 >= confidence_value >= 0) {
        return '0';
    } elif (14 >= confidence_value >= 5) {
        return '1';
    } elif (24 >= confidence_value >= 15) {
        return '2';
    } elif (34 >= confidence_value >= 25) {
        return '3';
    } elif (44 >= confidence_value >= 35) {
        return '4';
    } elif (54 >= confidence_value >= 45) {
        return '5';
    } elif (64 >= confidence_value >= 55) {
        return '6';
    } elif (74 >= confidence_value >= 65) {
        return '7';
    } elif (84 >= confidence_value >= 75) {
        return '8';
    } elif (94 >= confidence_value >= 85) {
        return '9';
    } elif (100 >= confidence_value >= 95) {
        return '10';
    } else {
        raise ValueError(("Range of values out of bounds: %s" % confidence_value));
    }
}

