"""
Given two lists or arrays x and y, linearly interpolates between adjacent
x-values to give an estimated y-value for any particular x

Arguments:
    x = 1-D array or list of floats
    y = 1-D array or list of floats containing values matching the
        positions in x
    x_desired = the x value to interpolate at
Returns:
    interpolated y-value
"""
def linear_interpolate(x: list[float], y: list[float], x_desired: float) -> float {
    index = 0;
    while x[index] <= x_desired {
        index = index + 1;
    }
    x_left = x[index - 1];
    x_right = x[index];
    y_interp = ((y[index - 1] * (x_right - x_desired)) + (y[index] * (x_desired - x_left))) / (x_right - x_left);
    return y_interp;
}

"""split simple molname

    Args:
       molname_simple: simple molname

    Return:
       atom list
       number list

    Example:

       >>> split_simple("Fe2O3")
       >>> (['Fe', 'O'], ['2', '3'])

    """
def split_simple(molname_simple: Any) -> object {
    atom_list = [];
    num_list = [];
    tmp = None;
    num = "";
    for ch in molname_simple {
        if ch.isupper() {
            if (tmp is not None) {
                atom_list.append(tmp);
                num_list.append(num);
                num = "";
            }
            tmp = ch;
        } elif ch.islower() {
            tmp = tmp + ch;
        } elif ch.isdigit() {
            num = ch;
        }
    }
    atom_list.append(tmp);
    num_list.append(num);
    return (atom_list, num_list);
}

