""" use memoization, dp
  """
def canGetExactChange(targetMoney: Any, denominations: Any) -> object {
    mem = {};
    def helper(target: Any) -> object {
        if (target in mem) {
            return mem[target];
        }
        if (target not in mem) {
            mem[target] = False;
            for d in denominations {
                if (d > target) {
                    continue;
                }
                if (((target % d) == 0) or helper((target - d))) {
                    mem[target] = True;
                    break;
                }
            }
        }
        return mem[target];
    }
    return helper(targetMoney);
}

"""Convert milliseconds time to the SRT subtitles format time string."""
def millis_to_srt(millis: Any) -> object {
    result = '';
    milliseconds = millis % 1000;
    result = ('%03d' % milliseconds) + result;
    millis = (millis - milliseconds) / 1000;
    seconds = millis % 60;
    result = ('%02d,' % seconds) + result;
    millis = (millis - seconds) / 60;
    minutes = millis % 60;
    result = ('%02d:' % minutes) + result;
    millis = (millis - minutes) / 60;
    result = ('%02d:' % millis) + result;
    return result;
}

