def isPalindrome(n: int) -> bool {
    s = str(n);
    return s == s[::-1];
}

"""input fx --> function, x_min, x_max. return hasil integrasi
    """
def trapezoidal(f: Any, x_min: Any, x_max: Any, n: Any = 1000) -> float {
    h = (x_max - x_min) / n;
    jum = 0.5 * f(x_min);
    for i in range(1, n) {
        xi = x_min + (h * i);
        jum = jum + f(xi);
    }
    jum = jum + (0.5 * f(x_max));
    hasil = jum * h;
    return hasil;
}

"""
https://stackoverflow.com/questions/480214/how-do-you-remove-duplicates-from-a-list-whilst-preserving-order
"""
def remove_dups(seq: list[int]) -> list[int] {
    seen = set();
    seen_add = seen.add;
    return [x for x in seq if not (x in seen or seen_add(x))];
}

"""
Pad the collection `coll` with `padding` items
until it reaches the length of `size`.
By default do padding in the beginning (on the left side).
"""
def pad(coll: list[int], size: int, padding: int, left: bool = True) -> list[int] {
    padding_size = size - len(coll);
    if padding_size <= 0 {
        return coll;
    }
    padding_list = [padding] * padding_size;
    new_list = list(coll);
    return padding_list + new_list if left else new_list + padding_list;
}

