"""encode_packet

    Take an already encoded data string and encode it to a BitShuffle data
    packet.

    :param data: bytes
    """
def encode_packet(
    data: Any, checksum: Any, seqnum: Any, seqmax: Any, compression: Any
) -> object {
    msg = (
        "This is encoded with BitShuffle, which you can download "
        + "from https://github.com/charlesdaniels/bitshuffle"
    );
    compatlevel = "1";
    encoding = "base64";
    data = data.decode(encoding="ascii");
    fmt = "((<<{}|{}|{}|{}|{}|{}|{}|{}>>))";
    packet = fmt.format(
        msg, compatlevel, encoding, compression, seqnum, seqmax, checksum, data
    );
    return packet;
}

