"""Converts a coordinate made by a letter/number couple in the index usable with the array that represents the board"""
def row_column_translation(row: Any, col: Any) -> object {
    row = int(row) - 1;
    if ((row % 2) != 0) {
        cols = range(ord("a"), (ord("a") + 7), 2);
    } else {
        cols = range(ord("b"), (ord("b") + 7), 2);
    }
    if (ord(col) not in cols) {
        return (-1, -1);
    } else {
        return (row, cols.index(ord(col)));
    }
}

""" generate aligned row """
def create_row(*fields: tuple[str, int, int, str]) -> str {
    row = "";
    for field in fields {
        (value, width, padding, alignment) = (field[0], field[1], field[2], field[3]);
        value = value[:width - padding] + ".." if len(value) > width - padding else value;
        if alignment == 'right' {
            row += value + (width - len(value)) * ' ';
        } else {
            row += (width - len(value) - padding) * ' ' + value + padding * ' ';
        }
    }
    return row;
}

