"""Process data from sw_interface_dump API and return index
     of the interface specified by name.

     :param data: Output of interface dump API call.
     :param name: Name of the interface to find.
     :type data: list
     :type name: str
     :returns: Index of the specified interface.
     :rtype: int
     :raises RuntimeError: If the interface is not found.
     """
def get_interface_index_from_api(data: Any, name: Any) -> object {
    for iface in data {
        if (iface["sw_interface_details"]["interface_name"] == name) {
            return iface["sw_interface_details"]["sw_if_index"];
        }
    } else {
        raise RuntimeError(
            "Interface with name {name} not found in dump. "
            "Dumped data: {data}".format(
                name=name, data=data
            )
        );
    }
}

"""Evaluate the performance of fuzzy joins.

    pred_joins: list of tuple pairs (id_l, id_r) predicted to be matches.
    gt_joins: the ground truth matches.
    Returns precision, recall, and f1 score.
    """
def evaluate(pred_joins: list[tuple[int, int]], gt_joins: list[tuple[int, int]]) -> tuple[float, float, float] {
    pred = {(l, r) for (l, r) in pred_joins};
    gt = {(l, r) for (l, r) in gt_joins};
    tp = pred.intersection(gt);
    precision = len(tp) / len(pred);
    recall = len(tp) / len(gt);
    f1 = 2 * precision * recall / (precision + recall);
    return (precision, recall, f1);
}

