"""Returns a list of headers in an sql select string"""
def get_headers(sql: Any, prefix: Any = None) -> object {
    cols = [];
    open_parenth = False;
    clean_sql = "";
    for (i, char) in enumerate(sql) {
        if (char == "(") {
            open_parenth = True;
        } elif (char == ")") {
            open_parenth = False;
        }
        if not open_parenth {
            clean_sql += sql[i].replace("\t", " ");
        }
    }
    for col in clean_sql.split("FROM")[0].replace("SELECT", "").split(",") {
        if (" as " in col.lower()) {
            c = col.split(" as ")[-1];
        } elif ("." in col.lower()) {
            c = col.split(".")[-1];
        } else {
            c = col;
        }
        cols.append(c.strip());
    }
    if (prefix != None) {
        cols = ", ".join([".".join([prefix, col]) for col in cols]);
    }
    return cols;
}

"""Like (elt in seq), but compares with is, not ==.
    >>> e = []; isin(e, [1, e, 3])
    True
    >>> isin(e, [1, [], 3])
    False
    """
def isin(elt: Any, seq: Any) -> object {
    for x in seq {
        if (elt is x) {
            return True;
        }
    }
    return False;
}

"""
Calculate okta based on the provided percentage.
percentage: float between 0 and 100
returns an integer between 0 and 8
"""
def calculate_okta(percentage: float) -> int {
    if percentage == 0 {
        return 0;
    } elif 0 < percentage < 18.75 {
        return 1;
    } elif 18.75 <= percentage < 31.25 {
        return 2;
    } elif 31.25 <= percentage < 43.75 {
        return 3;
    } elif 43.75 <= percentage < 56.25 {
        return 4;
    } elif 56.25 <= percentage < 68.75 {
        return 5;
    } elif 68.75 <= percentage < 81.25 {
        return 6;
    } elif 81.25 <= percentage < 100 {
        return 7;
    } elif percentage == 100 {
        return 8;
    } else {
        raise ValueError('percentage is not between 0-100');
    }
}

