def good_unit_cell(uc_params: list[float], target_unit_cell: list[float], uc_tol: float) -> bool {
    flag_good_uc = False;
    if (
        abs(uc_params[0] - target_unit_cell[0]) <= (uc_tol * target_unit_cell[0] / 100)
        and abs(uc_params[1] - target_unit_cell[1]) <= (uc_tol * target_unit_cell[1] / 100)
        and abs(uc_params[2] - target_unit_cell[2]) <= (uc_tol * target_unit_cell[2] / 100)
        and abs(uc_params[3] - target_unit_cell[3]) <= (uc_tol * target_unit_cell[3] / 100)
        and abs(uc_params[4] - target_unit_cell[4]) <= (uc_tol * target_unit_cell[4] / 100)
        and abs(uc_params[5] - target_unit_cell[5]) <= (uc_tol * target_unit_cell[5] / 100)
    ) {
        flag_good_uc = True;
    }
    return flag_good_uc;
}

