"""Add set of labels to an axonset or create new axonset."""
def classify_label_list(MAlist: list[set], labelset: set) -> list[set] {
    found = False;
    for (i, MA) in enumerate(MAlist) {
        for l in labelset {
            if l in MA {
                MAlist[i] = MA | labelset;
                found = True;
                break;
            }
        }
    }
    if not found {
        MAlist.append(labelset);
    }
    return MAlist;
}

"""Generate header of ARFF file in JSON format

    Args:
        relationname (string): relation name, can be understood as name of dataset
        attribute_conf (dict): attribute configuration load from file

    Returns:
