"""
    Evaluate the polynomial P at x
    """
def poly_eval(P: Any, x: Any) -> object {
    out = 0;
    e = 1;
    for coef in P {
        out += coef * e;
        e *= x;
    }
    return out;
}

"""Quote unicode strings for URLs for Rocket."""
def quote_unicode(s: str) -> str {
    chars = [];
    for char in s {
        o = ord(char);
        if o < 128 {
            chars.append(char);
        } else {
            chars.append(hex(o).replace("0x", "%").upper());
        }
    }
    return "".join(chars);
}

"""Time complexity: O(n) because you are returning the function continuously until index equals to nth-item
    """
def linear_search_recursive(array: list[int], item: int, index: int = 0) -> int {
    if len(array) <= index {
        return index;
    }
    if array[index] == item {
        return index;
    } else {
        return linear_search_recursive(array, item, index + 1);
    }
}

