"""Return a readable time format"""
def time_to_string(seconds: Any) -> object {
    if (seconds == 0) {
        return '0 seconds';
    }
    (h, s) = divmod(seconds, 3600);
    (m, s) = divmod(s, 60);
    if (h != 1) {
        h_s = 'hours';
    } else {
        h_s = 'hour';
    }
    if (m != 1) {
        m_s = 'minutes';
    } else {
        m_s = 'minute';
    }
    if (s != 1) {
        s_s = 'seconds';
    } else {
        s_s = 'second';
    }
    time_string = '';
    if h {
        time_string = f'{int(h)} {h_s}, {int(m)} {m_s} and {int(s)} {s_s}';
    } elif m {
        time_string = f'{int(m)} {m_s} and {int(s)} {s_s}';
    } else {
        time_string = f'{int(s)} {s_s}';
    }
    return time_string;
}

