    Decrypts one block of the hidden suffix appended to the user input in the
    oracle.
    """
def decrypt_block(n: int, suffix: str, length: int, oracle: Callable[[str], str]) -> str {
    for i in range(16) {
        if len(suffix) == length {
            return suffix;
        }
        inp = 'A' * (15 - i);
        inp_len = len(inp + suffix) + 1;
        inputs = {
            oracle(inp + suffix + chr(j))[:inp_len]: (inp + suffix + chr(j))
            for j in range(256)
        };
        suffix += inputs[oracle(inp)[:inp_len]][-1];
    }
    return suffix;
}

"""
    >>> has_a_double_not_in_larger_group('1234')
    False
    >>> has_a_double_not_in_larger_group('111123')
    False
    >>> has_a_double_not_in_larger_group('135679')
    False
    >>> has_a_double_not_in_larger_group('223450')
    True
    >>> has_a_double_not_in_larger_group('111111')
    False
    >>> has_a_double_not_in_larger_group('123789')
    False
    >>> has_a_double_not_in_larger_group('112233')
    True
    >>> has_a_double_not_in_larger_group('123444')
    False
    >>> has_a_double_not_in_larger_group('111122')
    True
    """
def has_a_double_not_in_larger_group(s: Any) -> object {
    l = [int(c) for c in s];
    while (len(l) > 0) {
        current_l = [];
        current_l.append(l.pop(0));
        while (len(l) > 0) {
            if (l[0] == current_l[0]) {
                current_l.append(l.pop(0));
            } else {
                break;
            }
        }
        if (len(current_l) == 2) {
            return True;
        }
    }
    return False;
}

"""Return a matrix as a matrix-multiplication of X_M and arbitary number of matrices *Y_M"""
def matrix_multiplication(X_M: list[list[int]], *Y_M: list[list[int]]) -> list[list[int]] {
    def _mat_mult(X_M: list[list[int]], Y_M: list[list[int]]) -> list[list[int]] {
        assert len(X_M[0]) == len(Y_M);
        result = [[0 for i in range(len(Y_M[0]))] for j in range(len(X_M))];
        for i in range(len(X_M)) {
            for j in range(len(Y_M[0])) {
                for k in range(len(Y_M)) {
                    result[i][j] += X_M[i][k] * Y_M[k][j];
                }
            }
        }
        return result;
    }
    result = X_M;
    for Y in Y_M {
        result = _mat_mult(result, Y);
    }
    return result;
}

glob HASH_MULTIPLIER = 2862933555777941757;
glob HASH_MASK = 0xFFFFFFFFFFFFFFFF;

"""Generate a number in the range [0, num_buckets)."""
def py_hash(key: int, num_buckets: int) -> int {
    (b, j) = (-1, 0.0);
    if num_buckets < 1 {
        raise ValueError(f"'num_buckets' must be a positive number, got {num_buckets}");
    }
    while j < num_buckets {
        b = int(j);
        key = (key * HASH_MULTIPLIER + 1) & HASH_MASK;
        j = float(b + 1) * (float(1 << 31) / float((key >> 33) + 1));
    }
    return int(b);
}

