"""Parses the word and counts the number of digits, lowercase letters,
    uppercase letters, and symbols. Returns a dictionary with the results.
    If any character in the word is not in the set of digits, lowercase
    letters, uppercase letters, or symbols it is marked as a bad character.
    Words with bad characters are not output."""
def parse_word(word: str, s: str) -> dict[str, int] {
    count = {'d': 0, 'l': 0, '': 0, 's': 0, 'x': 0};
    d = '0123456789';
    l = 'abcdefghijklmnopqrstuvwxyz';
    u = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    for c in word {
        if c in d {
            count['d'] += 1;
        } elif c in l {
            count['l'] += 1;
        } elif c in u {
            count[''] += 1;
        } elif c in s {
            count['s'] += 1;
        } else {
            count['x'] += 1;
        }
    }
    return count;
}

"""
    Returns a short portion of the text that shows the first difference
    @ In, a, string, the first text element
    @ In, b, string, the second text element
    @ Out, shortText, string, resulting shortened diff
  """
def shortText(a: str, b: str) -> str {
    a = repr(a);
    b = repr(b);
    display_len = 20;
    half_display = display_len // 2;
    if len(a) + len(b) < display_len {
        return a + " " + b;
    }
    first_diff = -1;
    i = 0;
    while i < len(a) and i < len(b) {
        if a[i] == b[i] {
            i += 1;
        } else {
            first_diff = i;
            break;
        }
    }
    if first_diff >= 0 {
        start = max(0, first_diff - half_display);
    } else {
        first_diff = min(len(a), len(b));
        start = max(0, first_diff - half_display);
    }
    if start > 0 {
        prefix = "...";
    } else {
        prefix = "";
    }
    return (
        prefix
        + a[start:first_diff + half_display]
        + " "
        + prefix
        + b[start:first_diff + half_display]
    );
}

"""
    Apply a function ``func`` to object ``obj`` either by passing obj as the
    first argument to the function or, in the case that the func is a tuple,
    interpret the first element of the tuple as a function and pass the obj to
    that function as a keyword argument whose key is the value of the second
    element of the tuple.

    Parameters
    ----------
    func : callable or tuple of (callable, str)
        Function to apply to this object or, alternatively, a
        ``(callable, data_keyword)`` tuple where ``data_keyword`` is a
        string indicating the keyword of `callable`` that expects the
        object.
    *args : iterable, optional
        Positional arguments passed into ``func``.
    **kwargs : dict, optional
        A dictionary of keyword arguments passed into ``func``.

    Returns
    -------
    object : the return type of ``func``.
    """
def pipe(`obj: Any, func: Any, *args: Any, **kwargs: Any) -> object {
    if isinstance(func, `tuple) {
        (func, target) = func;
        if (target in kwargs) {
            msg = f"{target} is both the pipe target and a keyword argument";
            raise ValueError(msg);
        }
        kwargs[target] = `obj;
        return func(*args, **kwargs);
    } else {
        return func(`obj, *args, **kwargs);
    }
}

