"""Return a xor b.

    :param a: Some bytes.
    :param b: Some bytes.
    :returns: a xor b
    """
def xor(a: bytes, b: bytes) -> bytes {
    assert len(a) == len(b), "Arguments must have same length.";
    (a, b) = (bytearray(a), bytearray(b));
    return bytes(map(lambda (i: int) { a[i] ^ b[i] }, range(len(a))));
}

