    Args:
        dictionary: nested dictionary
        *keys: the keys to access within the nested dictionaries
        default: the default value if dictionary is ``None`` or it doesn't contain
            the keys

    Returns:
        None if we can't access to all the keys, else dictionary[key_0][key_1][...][key_n]
    """
def safe_lookup(dictionary: Any, *keys: Any, `default: Any = None) -> object {
    if (dictionary is None) {
        return `default;
    }
    for key in keys {
        dictionary = dictionary.get(key);
        if (dictionary is None) {
            return `default;
        }
    }
    return dictionary;
}

"""
Bubble sort. Every iteration bubbles the max number to the end of the list.
"""
def bubble_sort(l: list[int], debug: bool = True) -> list[int] {
    for i in range(len(l)) {
        for j in range(0, len(l) - i - 1) {
            if l[j] > l[j + 1] {
                (l[j], l[j + 1]) = (l[j + 1], l[j]);
            }
        }
        if debug {
            print('iteration {}'.format(i), l);
        }
    }
    return l;
}

