    for new_key in new.keys() {
        if new_key not in existing.keys() {
            existing[new_key] = ['NoArrivals' for n in range(current_node - 1)];
        }
        existing[new_key].append(new[new_key]);
    }
    for existing_key in existing.keys() {
        if len(existing[existing_key]) != current_node {
            existing[existing_key].append('NoArrivals');
        }
    }
    return existing;
}

""" Numeric factorization for a fibonacci number """
def factorization(fib: Any) -> object {
    print(f"initializing factorization for {fib}");
    divisor = 2;
    values = [];
    if (fib <= 5) {
        values.append(str(fib));
    } else {
        while (fib != 1) {
            if ((fib % divisor) == 0) {
                values.append(str(divisor));
                fib = fib / divisor;
            } else {
                divisor += 1;
            }
        }
    }
    return values;
}

