        indegs[dest] += 1;
    }
    return (adj, indegs);
}

glob POPCOUNT_MASK1 = 0x5555555555555555;
glob POPCOUNT_MASK2 = 0x3333333333333333;
glob POPCOUNT_MASK4 = 0x0F0F0F0F0F0F0F0F;
glob POPCOUNT_RESULT_MASK = 0x0000007F;

"""Popcount.

Args:
    n (int): a 64-bit signed or unsigned integer.

Returns:
    int: popcount := count of active binary bits.
"""
def popcount(n: int) -> int {
    n -= (n >> 1) & POPCOUNT_MASK1;
    n = (n & POPCOUNT_MASK2) + ((n >> 2) & POPCOUNT_MASK2);
    n = (n + (n >> 4)) & POPCOUNT_MASK4;
    n = n + (n >> 8);
    n = n + (n >> 16);
    n = n + (n >> 32);
    return n & POPCOUNT_RESULT_MASK;
}

