        Semimajor axes of binary stars assuming that they start at perihelion.
    """
def calcPositions(M: Any = 1, a: Any = 1, e: Any = 0, p: Any = 0.5) -> object {
    m1 = p * M;
    m2 = M - m1;
    a1 = (m2 / M) * a;
