glob RED_MASK = 0xF8;
glob GREEN_MASK = 0xFC;

"""Convert red, green and blue values (0-255) into a 16-bit 565 encoding.  As
    a convenience this is also available in the parent adafruit_rgb_display
    package namespace."""
def color565(r: int | tuple[int, int, int], g: int = 0, b: int = 0) -> int {
    try {
        (r, g, b) = r;
    } except TypeError {
        ;
    }
    return (r & RED_MASK) << 8 | (g & GREEN_MASK) << 3 | b >> 3;
}

"""
    Gets pairs of three whose sum is 0

    Parameters:
        a : array
        s : sum to find equivalent to

    Returns:
        1 : If triplets found
        0 : if triplets not found
    """
def three_sum(a: list[int], s: int) -> int {
    a.sort();
    answer_set = [];
    for i in range(len(a) - 3) {
        l = i + 1;
        r = len(a) - 1;
        while r > l {
            if a[i] + a[r] + a[l] == s and a[r] > a[l] > a[i] {
                answer_set.append((a[i], a[r], a[l]));
                l += 1;
            } elif a[i] + a[r] + a[l] < s {
                l += 1;
            } else {
                r -= 1;
            }
        }
    }
    if answer_set {
        return 1;
    }
    return 0;
}

"""
        Go through each character in the string and map them to a dictionary
        where the key is the character and the value is the time that character appear
        in the string.

        Because the dictionary doesn't store thing in order. Therefore, we cannot loop
        through the dictionary and check if the value equal to 1 then return because
        there will be a case that it's not the order that we put in. (maybe the last one,
        but we expect the first one)

        So we have 2 options:
            1. Use another data structure, stack, to track back
            2. Simply loop through the given string again and return if that character count
            is 1. This time, it always the first one.
    """
def non_repeating(given_string: str) -> str | None {
    char_count = {};
    for char in given_string {
        if char not in char_count {
            char_count[char] = 1;
        } else {
            char_count[char] += 1;
        }
    }
    for char in given_string {
        if char_count[char] == 1 {
            return char;
        }
    }
    return None;
}

