def fix_template_expansion(content: str, replacements: list[dict[str, str]]) -> str {
    for replacement in replacements {
        for (key, to_be_replaced) in replacement.items() {
            new_replacement = (
                chr(123) + chr(123) + 'cookiecutter.' + key + chr(125) + chr(125)
            );
            content = content.replace(to_be_replaced, new_replacement);
        }
    }
    return content;
}

glob BYTES_PER_UNIT = 1000;

"""
    Convert a string (e.g. "5M") to number of bytes (int)
    """
def strformat_to_bytes(strformat: str) -> int {
    suffixes = {'B': 1};
    suffixes['K'] = BYTES_PER_UNIT * suffixes['B'];
    suffixes['M'] = BYTES_PER_UNIT * suffixes['K'];
    suffixes['G'] = BYTES_PER_UNIT * suffixes['M'];
    suffixes['T'] = BYTES_PER_UNIT * suffixes['G'];
    suffix = strformat[-1];
    amount = int(strformat[:-1]);
    return amount * suffixes[suffix];
}

