"""Skip over any garbage in the stream, properly handling escaped (!)
characters, and counting all characters. Returns the number of garbage
characters."""
def garbage(stream: Iterator[str]) -> int | None {
    count = 0;
    for c in stream {
        if c == '!' {
            next(stream);
        } elif c == '>' {
            return count;
        } else {
            count += 1;
        }
    }
}

"""
    Checks if two given sites are an anion and a cation.
    :param valences: list of site valences
    :param ii: index of a site
    :param jj: index of another site
    :return: True if one site is an anion and the other is a cation (from the valences)
    """
def is_anion_cation_bond(valences: Any, ii: Any, jj: Any) -> object {
    if (valences == "undefined") {
        return True;
    }
    if ((valences[ii] == 0) or (valences[jj] == 0)) {
        return True;
    }
    return ((valences[ii] > 0 > valences[jj]) or (valences[jj] > 0 > valences[ii]));
}

"""
    Return modular inverse using a version Euclid's Algorithm
    Code by Andrew Kuchling in Python Journal:
    http://www.pythonjournal.com/volume1/issue1/art-algorithms/
    -- in turn also based on Knuth, vol 2.
    """
def invmod(a: int, b: int) -> int {
    (a1, a2, a3) = (1, 0, a);
    (b1, b2, b3) = (0, 1, b);
    while b3 != 0 {
        q = a3 / b3;
        t = (a1 - b1 * q, a2 - b2 * q, a3 - b3 * q);
        (a1, a2, a3) = (b1, b2, b3);
        (b1, b2, b3) = t;
    }
    while a2 < 0 {
        a2 = a2 + a;
    }
    return a2;
}

