    Returns:
         age (float): approximate age
    """
def eye_to_age(D_eye: float) -> int {
    if D_eye > 7.25 {
        age = 15;
    } elif D_eye <= 7.25 and D_eye > 6.75 {
        age = 25;
    } elif D_eye <= 6.75 and D_eye > 6.25 {
        age = 33;
    } elif D_eye <= 6.25 and D_eye > 5.75 {
        age = 40;
    } elif D_eye <= 5.75 and D_eye > 5.25 {
        age = 54;
    } else {
        age = 70;
    }
    return age;
}

