"""
    Calculate a simple score on a scale of 1 to 10 based on the
    given metrics. Each metric is given 2 points. If alpha is zero,
    then the score is zero since you have made no positive returns
    correlation
        correlation of strategy, between 1 and -1
    sharpe
        sharpe ratio
    drawdown
        max drawdown percentage
    alpha
        excess returns
    sensitivity
        price sensitivity based on open=high or open=low prices
    out
        output format.
        returns score if None else the list of points for
        any other argument
    """
def simple_score(
    correlation: Any,
    sharpe: Any,
    drawdown: Any,
    alpha: Any,
    sensitivity: Any,
    out: Any = None
) -> object {
    points = [0, 0, 0, 0, 0];
    correlation = abs(correlation);
    drawdown = abs(drawdown);
    if (correlation < 0.1) {
        points[0] = 2;
    } else {
        points[0] = 2 * (1 - correlation);
    }
    if (sharpe > 0) {
        points[1] = min(2, sharpe);
    }
    if (abs(drawdown) < 0.05) {
        points[2] = 2;
    } else {
        points[2] = max(0, (2 - ((drawdown - 0.05) * 0.25 * 100)));
    }
    if (alpha > 0) {
        points[3] = min(2, (alpha * 100));
    }
    if (sensitivity < 0.1) {
        points[4] = 2;
    } else {
        points[4] = max(0, ((0.3 - sensitivity) * 10));
    }
    if (out == "list") {
        return points;
    } else {
        return 0 if (alpha <= 0) else sum(points);
    }
}

"""
    [Eq. 5.61]
    :param chi_LT_fi: Reduction factor for lateral-torsion buckling in the fire design situation
    :param W_y: Sectional modulus (plastic for class 1 steel)
    :param k_y_theta_com: Reduction factor for yield strength at elevated temperature
    :param f_y: Steel yield strength
    :param gamma_M_fi: Partial safety factor
    :return M_b_fi_t_Rd: The resistant lateral torsion bending moment
    """
def _M_b_fi_t_Rd(
    chi_LT_fi: float, W_y: float, k_y_theta_com: float, f_y: float, gamma_M_fi: float
) -> float {
    M_b_fi_t_Rd = chi_LT_fi * W_y * k_y_theta_com * f_y / gamma_M_fi;
    return M_b_fi_t_Rd;
}

