"""Convert numbers in word form to integers."""
def text_to_int(textnum: Any) -> object {
    numwords = {};
    units = [
        "zero",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen"
    ];
    tens = [
        "",
        "",
        "twenty",
        "thirty",
        "forty",
        "fifty",
        "sixty",
        "seventy",
        "eighty",
        "ninety"
    ];
    modifiers = ["", "quarter", "half", "three-quarters"];
    numwords["and"] = 0;
    numwords["a"] = 0;
    for (idx, word) in enumerate(units) {
        numwords[word] = idx;
    }
    for (idx, word) in enumerate(tens) {
        numwords[word] = idx * 10;
    }
    for (idx, word) in enumerate(modifiers) {
        numwords[word] = idx * 0.25;
    }
    current = 0;
    for word in textnum.split() {
        if (word not in numwords) {
            raise ValueError(("Illegal word: " + word));
        }
        current += numwords[word];
    }
    return current;
}

"""Return the django permcode for the specified method.

    eg. "POST" => "add"
    """
def method_to_permcode(method: str) -> str {
    method = method.upper();
    match method {
        case "POST":
            return "add";
        case "GET":
            return "view";
        case "PUT" | "UPDATE":
            return "change";
        case "DELETE":
            return "delete";
    }
    raise ValueError("Could not derive perm code from method %s" % method);
}

"""Helper function to determine which font color to use"""
def font_color_helper(
    background_color: str, light_color: str | None = None, dark_color: str | None = None
) -> str {
    light_color = light_color if light_color is not None else "#FFFFFF";
    dark_color = dark_color if dark_color is not None else "#000000";
    tmp_color = background_color.strip().strip('#');
    tmp_r = int(tmp_color[:2], 16);
    tmp_g = int(tmp_color[2:4], 16);
    tmp_b = int(tmp_color[4:], 16);
    font_color_code = dark_color if (tmp_r * 0.299) + (tmp_g * 0.587) + (tmp_b * 0.114) > 186 else light_color;
    return font_color_code;
}

