"""
:param data: this is a caching efficiency dictionary in a string format
:return: the python dictionary format of the data string
"""
def convertJsonToDictionary(data: str) -> dict[str, list[str] | list[int] | list[float]] {
    output: dict[str, list[str] | list[int] | list[float]] = {
        "#Payloads": [],
        "#queries": [],
        "#uniqueQueries": [],
        "PayloadSize (MB)": [],
        "folders": []
    };
    data = data.strip('{}');
    components = data.split(',"');
    folders_value = '';
    for comp in components[4:] {
        if folders_value {
            folders_value += ',"';
        }
        folders_value += comp;
    }
    components = components[:4] + [folders_value];
    for comp in components {
        elements = comp.split(':');
        (key, value) = (elements[0].strip('"'), elements[1].strip('[]'));
        if key == "folders" {
            parts = value.split('","');
            for val in parts {
                output["folders"].append(val.strip('"'));
            }
        } else {
            parts = value.split(',');
            if key == "PayloadSize (MB)" {
                output[key] = [float(val) for val in parts];
            } else {
                output[key] = [int(val) for val in parts];
            }
        }
    }
    return output;
}

"""
    Prints the average precision for each class and calculates micro mAP and macro mAP.
    @param aps: average precision for each class
    @param dictionary: mapping between label anc class name
    @return: micro mAP and macro mAP
    """
def calculate_map(aps: Any) -> object {
    total_instances = [];
    precisions = [];
    for (label, (average_precision, num_annotations)) in aps.items() {
        total_instances.append(num_annotations);
        precisions.append(average_precision);
    }
    if (sum(total_instances) == 0) {
        print('No test instances found.');
        return (0, 0);
    }
    micro_ap = (
        sum([(a * b) for (a, b) in zip(total_instances, precisions)])
        / sum(total_instances)
    );
    macro_ap = sum(precisions) / sum((x > 0) for x in total_instances);
    print('Micro mAP : {:.4f}'.format(micro_ap));
    print('Macro mAP: {:.4f}'.format(macro_ap));
    return (micro_ap, macro_ap);
}

"""
Returns a segment of a string, starting at start_num. The first character in text has
start_num 1.

>>> MID("Fluid Flow", 1, 5)
'Fluid'
>>> MID("Fluid Flow", 7, 20)
'Flow'
>>> MID("Fluid Flow", 20, 5)
''
>>> MID("Fluid Flow", 0, 5)
Traceback (most recent call last):
...
ValueError: start_num invalid
"""
def MID(text: str, start_num: int, num_chars: int) -> str {
    if start_num < 1 {
        raise ValueError("start_num invalid");
    }
    return text[start_num - 1:start_num - 1 + num_chars];
}

"""
Checks for existence of a bijection between input sequences
seq1 and seq2.
"""
def is_equivalent(seq1: str, seq2: str) -> bool {
    letters1 = set(seq1);
    letters2 = set(seq2);
    distinct_mappings = set(zip(seq1, seq2));
    return (
        len(letters1) == len(letters2) == len(distinct_mappings)
        and len(seq1) == len(seq2)
    );
}

