    """
def check_numbers_unique(number_list: list[int | str]) -> bool {
    number_set = set();
    for number in number_list {
        if number not in number_set {
            if number not in [' ', '*'] {
                number_set.add(number);
            }
        } else {
            return False;
        }
    }
    return True;
}

"""[1,2,3,4,5,6,7]"""
def reorderOddEvent(nums: Any) -> object {
    def event(num: Any) -> object {
        return ((num % 2) == 0);
    }
    (leftIndex, rightIndex) = (0, (len(nums) - 1));
    while (leftIndex < rightIndex) {
        while ((leftIndex < rightIndex) and not event(nums[leftIndex])) {
            leftIndex += 1;
        }
        while ((leftIndex < rightIndex) and event(nums[rightIndex])) {
            rightIndex -= 1;
        }
        if (leftIndex < rightIndex) {
            (nums[leftIndex], nums[rightIndex]) = (nums[rightIndex], nums[leftIndex]);
        }
    }
    return nums;
}

