"""Shorten a string (with an ellipsis) if it is longer than certain length."""
def str_truncate(text: str, width: int = 64, ellipsis: str = "...") -> str {
    assert width >= 0;
    if len(text) <= width {
        return text;
    }
    if len(ellipsis) > width {
        ellipsis = ellipsis[:width];
    }
    return text[:max(0, width - len(ellipsis))] + ellipsis;
}

"""Separate arguments passed to J2ObjC into source files and J2ObjC flags.

    Args:
        j2objc_args: A list of args to pass to J2ObjC transpiler.
    Returns:
        A tuple containing source files and J2ObjC flags
    """
def _ParseArgs(j2objc_args: list[str]) -> tuple[list[str], list[str]] {
    source_files = [];
    flags = [];
    is_next_flag_value = False;
    for j2objc_arg in j2objc_args {
        if j2objc_arg.startswith('-') {
            flags.append(j2objc_arg);
            is_next_flag_value = True;
        } elif is_next_flag_value {
            flags.append(j2objc_arg);
            is_next_flag_value = False;
        } else {
            source_files.append(j2objc_arg);
        }
    }
    return (source_files, flags);
}

"""Edits two given strings and compare them.

    Returns True if both edited arguments are equal, otherwise False.
    """
def backspace_compare(first: str, second: str) -> bool {
    first_index = len(first) - 1;
    second_index = len(second) - 1;
    skip_in_first = 0;
    skip_in_second = 0;
    while first_index >= 0 or second_index >= 0 {
        if first[first_index] == "#" {
            skip_in_first += 1;
            first_index -= 1;
            continue;
        } elif skip_in_first > 0 {
            first_index -= 1;
            skip_in_first -= 1;
            continue;
        }
        if second[second_index] == "#" {
            skip_in_second += 1;
            second_index -= 1;
            continue;
        } elif skip_in_second > 0 {
            second_index -= 1;
            skip_in_second -= 1;
            continue;
        }
        if (first_index >= 0 and second_index < 0) or (first_index < 0 and second_index >= 0) {
            return False;
        }
        if first[first_index] != second[second_index] {
            return False;
        }
        first_index -= 1;
        second_index -= 1;
    }
    return True;
}

"""Check if str_1 and str_2 are permutations of each other.

    Uses str.count to calculate appearance frequency of each unique character.
    Raises TypeError if either argument is not a str.
    """
def is_permutation_nocounter(str_1: str, str_2: str) -> bool {
    if not isinstance(str_1, str) or not isinstance(str_2, str) {
        raise TypeError;
    }
    if len(str_1) != len(str_2) {
        return False;
    }
    str_1_char_freq = {char: str_1.count(char) for char in set(str_1)};
    str_2_char_freq = {char: str_2.count(char) for char in set(str_2)};
    return str_1_char_freq == str_2_char_freq;
}

"""Build an argv list from a Microsoft shell style cmdline str.

    The reverse of list2cmdline that follows the same MS C runtime rules.
    """
def cmdline2list(cmdline: str) -> list[str] {
    whitespace = ' \t';
    bs_count = 0;
    in_quotes = False;
    arg = [];
    argv = [];
    for ch in cmdline {
        if ch in whitespace and not in_quotes {
            if arg {
                argv.append(''.join(arg));
                arg = [];
            }
            bs_count = 0;
        } elif ch == '\\' {
            arg.append(ch);
            bs_count += 1;
        } elif ch == '"' {
            if not bs_count % 2 {
                if bs_count {
                    delete(arg[-(bs_count / 2):],);
                }
                in_quotes = not in_quotes;
            } else {
                delete(arg[-((bs_count / 2) + 1):],);
                arg.append(ch);
            }
            bs_count = 0;
        } else {
            arg.append(ch);
            bs_count = 0;
        }
    }
    if arg or in_quotes {
        argv.append(''.join(arg));
    }
    return argv;
}

"""
    This function can be passed to a reduce to determine the maximum length of
    a list within a list of lists.
    """
def max_length(x: Any, y: Any) -> object {
    if ((`type(x) == `list) and (`type(y) == `list)) {
        return max(len(x), len(y));
    } elif ((`type(x) == `list) and (`type(y) == int)) {
        return max(len(x), y);
    } elif ((`type(x) == int) and (`type(y) == `list)) {
        return max(x, len(y));
    } elif ((`type(x) == int) and (`type(y) == int)) {
        return max(x, y);
    }
    if ((`type(x) != int) or (`type(x) != `list)) {
        raise TypeError(("Invalid type: " + str(`type(x))));
    }
    if ((`type(y) != int) or (`type(y) != `list)) {
        raise TypeError(("Invalid type: " + str(`type(x))));
    }
}

