"""rol(int_type, size, offset) -> int

    Returns the value of int_type rotated left by (offset mod size) bits.
    """
def rol(int_type: int, size: int, offset: int) -> int {
    mask = (1 << size) - 1;
    offset %= size;
    left = (int_type << offset) & mask;
    circular = (int_type & mask) >> (size - offset);
    return left | circular;
}

"""
    modules is dict of otus, metadata is a dictionary of dictionaries where outer dict keys
    are features, inner dict keys are metadata names and values are metadata values
    """
def add_modules_to_metadata(modules: Any, metadata: Any) -> object {
    for (module_, otus) in modules.items() {
        for otu in otus {
            if (str(otu) in metadata) {
                metadata[str(otu)]['module'] = module_;
            } else {
                metadata[str(otu)] = `dict();
                metadata[str(otu)]['module'] = module_;
            }
        }
    }
    return metadata;
}

"""Compute gcd of two positive integers x and y"""
def compute_gcd(x: int, y: int) -> int {
    if x < y {
        return compute_gcd(y, x);
    }
    residual = x % y;
    if residual == 0 {
        return y;
    }
    if residual == 1 {
        return 1;
    }
    return compute_gcd(y, residual);
}

"""
