import numpy;

"""Spectral test to determine potential snow.

Uses the 9.85C (283K) threshold defined in Zhu, Woodcock 2015.
Returns a boolean ndarray where True is potential snow.
"""
def potential_snow_layer(ndsi: numpy.ndarray, green: numpy.ndarray, nir: numpy.ndarray, tirs1: numpy.ndarray) -> numpy.ndarray {
    return (ndsi > 0.15) & (tirs1 < 9.85) & (nir > 0.11) & (green > 0.1);
}

glob BYTE_MASK = 0x7F;
glob CONTINUATION_BIT = 0x80;

"""
Encode int -> uleb128

num -- int to encode
return -- bytearray with encoded number
"""
def uleb128Encode(num: int) -> bytearray {
    arr = bytearray();
    length = 0;
    if num == 0 {
        return bytearray(b'\x00');
    }
    while num > 0 {
        arr.append(num & BYTE_MASK);
        num = num >> 7;
        if num != 0 {
            arr[length] = arr[length] | CONTINUATION_BIT;
        }
        length += 1;
    }
    return arr;
}

"""
Convert a string to a more file name (and web) friendly format.

Parameters
----------
inString : str
    The input string to be sanitized. Typically these are combinations of metric names and metadata.

Returns
-------
str
    The string after removal/replacement of non-filename friendly characters.
"""
def nameSanitize(inString: str) -> str {
    outString = inString.replace('>', 'gt').replace('<', 'lt').replace('=', 'eq');
    outString = outString.replace(' ', '_').replace('.', '_').replace(',', '');
    outString = outString.replace('/', '_').replace('\\', '_');
    outString = outString.replace('(', '').replace(')', '');
    outString = outString.replace(':', '_').replace(';', '_');
    outString = outString.replace('%', '_').replace('#', '_');
    while '__' in outString {
        outString = outString.replace('__', '_');
    }
    return outString;
}

