"""Returns sizes in human-readable units. Input is kbytes"""
def humanreadablesize(kbytes: Any) -> object {
    try {
        kbytes = float(kbytes);
    } except (TypeError, ValueError, UnicodeDecodeError) {
        return "unknown";
    }
    units = [
        (" KB", (2 ** 10)),
        (" MB", (2 ** 20)),
        (" GB", (2 ** 30)),
        (" TB", (2 ** 40))
    ];
    for (suffix, limit) in units {
        if (kbytes > limit) {
            continue;
        } else {
            return (str(round((kbytes / float((limit / (2 ** 10)))), 1)) + suffix);
        }
    }
}

"""
OO  OO   OOO
    OOO  OOO
         OOOO
Number of Os:
2   4    7"""
def vis8(n: int) -> str {
    result = '';
    for i in range(1, n + 1) {
        result += 'O' * n;
        if i == n {
            result += 'O\n';
        } else {
            result += '\n';
        }
    }
    return result;
}

"""'Empty' TFRs are NOTAM-TFRs which are NOTAM-TFRs that have been
sent previously, and are active, but which every other cycle is sent
with no text-- Just with it's number, an empty text field, and an
indication that it is still active.

Args:
    frame (dict): Frame with product id of 8.

Returns:
    Empty string if this cannot be an empty TFR. Otherwise, a
    frame-string indicating that it is an EMPTY TFR."""
def detectEmptyTFR(frame: dict) -> str {
    if 'records' in frame['contents'] {
        records = frame['contents']['records'];
        for x in records {
            if 'report_status' in x and x['report_status'] == 0 {
                continue;
            }
            if 'text' in x and x['text'] == '' {
                return ' [EMPTY TFR {}-{}]'.format(x['report_year'], x['report_number']);
            }
        }
    }
    return '';
}

"""Returns s with all non-alphanumeric characters replaced with *

Parameters
----------
s : str
    The string to be censored.

Returns
-------
output : str
    The censored version of `s`"""
def censor_non_alphanum(s: str) -> str {
    def censor(ch: str) -> str {
        if (ch >= 'A' and ch <= 'z') or (ch >= '0' and ch <= '9') {
            return ch;
        }
        return '*';
    }
    return ''.join(censor(ch) for ch in s);
}

"""Return factorial.

    Args:
        n (int): Argument (non-negative)

    Returns:
        Factorial of n
    """
def factorial(n: int) -> int {
    assert `type(n) == int and n >= 0;
    if n == 0 {
        return 1;
    } else {
        return n * factorial(n - 1);
    }
}

"""
    The reflection coefficient
    Equation 8.15
    :param float tau_1: the transmission coefficients of the first layer
    :param float rho_1: the reflection coefficients of the first layer
    :param float rho_2: the reflection coefficients of the second layer
    :return: The reflection coefficient
    """
def double_layer_cover_reflection_coefficient(
    tau_1: float, rho_1: float, rho_2: float
) -> float {
    return rho_1 + (tau_1 * tau_1 * rho_2) / (1 - rho_1 * rho_2);
}

