"""
hsv: [h, s, v]
    h in [0, 360]
    s in [0, 1]
    v in [0, 1]
return [r, g, b]
    r, g, b in [0, 1]
"""
def hsv2rgb(hsv: list[float]) -> list[float] {
    h = hsv[0];
    s = hsv[1];
    v = hsv[2];
    hd = h / 60;
    r = v;
    g = v;
    b = v;
    if s > 0 {
        hdi = max(0, min(5, int(hd)));
        f = hd - hdi;
        match hdi {
            case 0:
                g *= 1 - s * (1 - f);
                b *= 1 - s;
            case 1:
                r *= 1 - s * f;
                b *= 1 - s;
            case 2:
                r *= 1 - s;
                b *= 1 - s * (1 - f);
            case 3:
                r *= 1 - s;
                g *= 1 - s * f;
            case 4:
                r *= 1 - s * (1 - f);
                g *= 1 - s;
            case 5:
                g *= 1 - s;
                b *= 1 - s * f;
        }
    }
    return [r, g, b];
}

"""Function to return a sorted list using the selection sort algorithm."""
def selection_sort(marks: list[int]) -> list[int] {
    for i in range(len(marks)) {
        min_idx = i;
        for j in range(i + 1, len(marks)) {
            if marks[min_idx] > marks[j] {
                min_idx = j;
            }
        }
        (marks[i], marks[min_idx]) = (marks[min_idx], marks[i]);
    }
    return marks;
}

