"""Calculate the max number of clones for a walker.

Parameters
----------
walker_weight : float
min_weight : float
max_num_walkers : int

Returns
-------
int
"""
def calc_max_num_clones(
    walker_weight: float, min_weight: float, max_num_walkers: int
) -> int {
    max_n_clones = 0;
    n_splits = 2;
    while (walker_weight / n_splits >= min_weight) and (n_splits <= max_num_walkers) {
        n_splits += 1;
    }
    n_splits -= 1;
    max_n_clones = n_splits - 1;
    return max_n_clones;
}

