"""Implementation of Bubble sort.

Takes integer list as input, returns sorted list."""
def bubble_sort(x: list[int]) -> list[int] {
    print("Starting Bubble sort on following list:\n", x);
    loop = 0;
    unsorted = True;
    while unsorted {
        loop += 1;
        print("Bubble sort is in iteration: ", loop);
        changes = 0;
        for i in range(0, len(x) - 1) {
            if x[i] > x[i + 1] {
                print("Bubble sort is changing position of: ", x[i], "and", x[i + 1]);
                j = x[i];
                x[i] = x[i + 1];
                x[i + 1] = j;
                changes += 1;
            }
        }
        if changes == 0 {
            unsorted = False;
        }
    }
    print("Bubble sort is finished. Sorted list is: \n", x);
    return x;
}

"""
Solve a*x + b*y = gcd(a, b)
:param a:
:param b:
:return: gcd, x, y
"""
def exgcd(a: int, b: int) -> tuple[int, int, int] {
    if a == 0 {
        return (b, 0, 1);
    }
    (g, y, x) = exgcd(b % a, a);
    return (g, x - (b // a) * y, y);
}

"""
:param x: time interval
:param p: model parameter
:param q: model parameter
:param n: model parameter
:return: variance of model
"""
def model_var_calculate(x: float, p: float, q: float, n: float) -> float {
    def alpha_(x: float) -> float {
        return n * (p * pow(x, 3) + q * (x * x) + (1 - p - q) * x);
    }
    def beta_(x: float) -> float {
        return n - alpha_(x);
    }
    return (alpha_(x) * beta_(x)) / ((alpha_(x) + beta_(x)) ** 2 * (alpha_(x) + beta_(x) + 1));
}

