"""Finds all occurrences of a pattern in a text of bases.

    Args:
        text: input string
        pattern: pattern to search for in string

    Returns:
        Running tally of how many occurrences of pattern were found in text.
    """
def pattern_count(text: str, pattern: str) -> int {
    count = 0;
    pattern_length = len(pattern);
    text_length = len(text);
    for i in range(text_length - pattern_length + 1) {
        if text[i:i + pattern_length] == pattern {
            count += 1;
        }
    }
    return count;
}

