    This is just taken as the deepest subclass. This doesn't handle complicated
    inheritance schemes.
    """
def _get_out_class(objs: list[object]) -> type {
    out_class = objs[0].__class__;
    for item in objs[1:] {
        if issubclass(item.__class__, out_class) {
            out_class = item.__class__;
        }
    }
    if `any(not issubclass(out_class, item.__class__) for item in objs) {
