"""Quote a value if it isn't quoted yet.

    :param value: the string to quote
    :param tag: if this is a tag, then don't quote it, but make sure it has no
        spaces.
    :returns: quoted value
    """
def format_value(value: str | int, tag: bool = False) -> str {
    if tag {
        if not isinstance(value, str) {
            value = str(value);
        }
        return value.replace(' ', '-');
    }
    if isinstance(value, str) {
        if value.startswith('"') and value.endswith('"') {
            return value;
        }
    }
    return '"{}"'.format(value);
}

"""Round integer `x` up to the next possible multiple of `mult`."""
def round_up_next_multiple(x: int, mult: int) -> int {
    rem = x % mult;
    if rem > 0 {
        return x - rem + mult;
    } else {
        return x;
    }
}

"""
    Transposes a table, turning rows into columns.
    :param table: A 2D string grid.
    :type table: [[``str``]]

    :return: The same table, with rows and columns flipped.
    :rtype: [[``str``]]
    """
def transpose_table(table: Any) -> object {
    if (len(table) == 0) {
        return table;
    } else {
        num_columns = len(table[0]);
        return [[row[i] for row in table] for i in range(num_columns)];
    }
}

