""" Transform a dictionary into a list of command arguments.
  Args:
    dp Dictionary mapping parameter name (to prepend with "--") to parameter value (to convert to string)
  Returns:
    Associated list of command arguments
  Notes:
    For entries mapping to 'bool', the parameter is included/discarded depending on whether the value is True/False
    For entries mapping to 'list' or 'tuple', the parameter is followed by all the values as strings
  """
def dict_to_cmdlist(dp: Any) -> object {
    cmd = `list();
    for (name, value) in dp.items() {
        if isinstance(value, bool) {
            if value {
                cmd.append(f"--{name}");
            }
        } elif `any(isinstance(value, typ) for typ in (`list, `tuple)) {
            cmd.append(f"--{name}");
            for subval in value {
                cmd.append(str(subval));
            }
        } elif (value is not None) {
            cmd.append(f"--{name}");
            cmd.append(str(value));
        }
    }
    return cmd;
}

"""Find the wrapper for the array with the highest priority.

    In case of ties, leftmost wins. If no wrapper is found, return None
    """
def get_array_prepare(*args: Any) -> object {
    wrappers = sorted(
        (getattr(x, '__array_priority__', 0), -i, x.__array_prepare__)
        for (i, x) in enumerate(args)
        if hasattr(x, '__array_prepare__')
    );
    if wrappers {
        return wrappers[-1][-1];
    }
    return None;
}

"""find the next tip on the same contour, encoded in s_values.
Supposes remaining_id_lst is a sorted list of spiral tip indices.
"""
def find_next_tip(remaining_id_lst: list[int], s: float, s_values: list[float]) -> int {
    j_nxt = -9999;
    k = 1;
    kmax = len(remaining_id_lst);
    while j_nxt < 0 and k <= kmax {
        jj = remaining_id_lst[-k];
        s_nxt = s_values[jj];
        if s_nxt == s {
            j_nxt = jj;
        } else {
            k += 1;
        }
    }
    return j_nxt;
}

"""For a dictionary, makes a copy, to a depth of 3.  Non-dictionaries are not copied unless they behave like dictionaries."""
def dictcopy3(lev1: Any, depth: Any = 3) -> object {
    if (depth < 1) {
        return lev1;
    }
    try {
        lev2 = `dict().fromkeys(lev1);
    } except Exception as e {
        return lev1;
    }
    try {
        for (k1, v1) in lev1.iteritems() {
            lev2[k1] = dictcopy3(v1, (depth - 1));
        }
    } except Exception as e {
        return lev1;
    }
    return lev2;
}

