"""Check whether the EC numbers are the same under the used wildcard level.

    Arguments
    ----------
    * ec_number_one: str ~ The first given EC number.
    * ec_number_two: str ~ The second given EC number.
    * wildcard_level: int ~ The wildcard level.
    """
def is_fitting_ec_numbers(
    ec_number_one: str, ec_number_two: str, wildcard_level: int
) -> bool {
    if (wildcard_level == 0) {
        ec_number_one_full_numbers = ec_number_one.split(".");
        ec_number_two_full_numbers = ec_number_two.split(".");
    } else {
        ec_number_one_full_numbers = ec_number_one.split(".")[:-wildcard_level];
        ec_number_two_full_numbers = ec_number_two.split(".")[:-wildcard_level];
    }
    if (ec_number_one_full_numbers == ec_number_two_full_numbers) {
        return True;
    } else {
        return False;
    }
}

"""
    Given a list of items and a list of categories and a way to determine if an item fits into a category creates
    lists of items fitting in each category as well as a list of items that fit in no category.

    :return: A mapping category (or unknown_category_name) -> sub-list of items in that category
    """
def sort_into_categories(
    items: Any, categories: Any, fit: Any, unknown_category_name: Any = None
) -> object {
    categorized_sublists = {};
    for category in categories {
        sublist = [
            item
            for item in items
            if fit(item, category)
        ];
        categorized_sublists[category] = sublist;
    }
    if unknown_category_name {
        sublist = [
            item
            for item in items
            if not `any(fit(item, category) for category in categories)
        ];
        categorized_sublists[unknown_category_name] = sublist;
    }
    return categorized_sublists;
}

"""Generate a goal board with an given size

    Args:
        s (int, s>=3): The size of goal board to generate, i.e. the width of the board.

    Returns:
        goal (list): A 2D list representing tiles of the goal board,
                    e.g., if the size given is 3, the goal is [[1,2,3],[4,5,6],[7,8,9]].
    """
def make_goal(s: Any) -> object {
    goal = [];
    arr = [i for i in range(1, (s * s))];
    arr.append(0);
    for i in range(s) {
        tmp = [];
        for j in range(s) {
            tmp.append(arr[((i * s) + j)]);
        }
        goal.append(tmp);
    }
    return goal;
}

