"""Calculate the nth fibonacci number using the seeds a and b."""
def fib1(a: int, b: int, n: int) -> int {
    if n == 1 {
        return a;
    } elif n == 2 {
        return b;
    } else {
        return fib1(a, b, n - 1) + fib1(a, b, n - 2);
    }
}

"""Modeled after the piecewise cubic
    y = (1/2)((2x)^3)       ; [0, 0.5)
    y = (1/2)((2x-2)^3 + 2) ; [0.5, 1]
    """
def cubic_ease_in_out(p: float) -> float {
    if p < 0.5 {
        return 4 * p * p * p;
    } else {
        f = (2 * p) - 2;
        return (0.5 * f * f * f) + 1;
    }
}

"""
    Implementation of bubble sort.
    O(n2) and thus highly ineffective.
    """
def bubble_sort(seq: list[int]) -> list[int] {
    size = len(seq) - 1;
    for num in range(size, 0, -1) {
        for i in range(num) {
            if seq[i] > seq[i + 1] {
                temp = seq[i];
                seq[i] = seq[i + 1];
                seq[i + 1] = temp;
            }
        }
    }
    return seq;
}

