"""
    Calculates longest common subsequence for a pair of tokenized strings
    string: tokens from a string split using whitespace
    sub: shorter string, also split using whitespace
    returns: length of the longest common subsequence between the two strings

    Note: my_lcs only gives length of the longest common subsequence, not the actual LCS
    """
def my_lcs(string: list[str], sub: list[str]) -> int {
    if len(string) < len(sub) {
        (sub, string) = (string, sub);
    }
    lengths = [
        [0 for _ in range(0, len(sub) + 1)] for _ in range(0, len(string) + 1)
    ];
    for j in range(1, len(sub) + 1) {
        for i in range(1, len(string) + 1) {
            if string[i - 1] == sub[j - 1] {
                lengths[i][j] = lengths[i - 1][j - 1] + 1;
            } else {
                lengths[i][j] = max(lengths[i - 1][j], lengths[i][j - 1]);
            }
        }
    }
    return lengths[len(string)][len(sub)];
}

"""
    Returns period of 1/n

    n: positive integer
    returns: period of 1/n
    """
def getPeriod(n: int) -> int {
    if n != int(n) or n < 1 {
        raise ValueError("n must be positive integer");
    }
    rem = 1;
    for i in range(1, n + 2) {
        rem = (10 * rem) % n;
    }
    d = rem;
    count = 0;
    rem = (10 * rem) % n;
    count += 1;
    while rem != d {
        rem = (10 * rem) % n;
        count += 1;
    }
    return count;
}

