"""Given a list of input integers, find the (first) two numbers which sum to the given target, and return them as a 2-tuple.

Return None if the sum could not be made."""
def find_sum(inputs: list[int], target: int) -> tuple[int, int] | None {
    for i in inputs {
        if i < target // 2 + 1 {
            if target - i in inputs {
                return (i, target - i);
            }
        }
    }
}

