"""Function to multiply a number by a digit"""
def rec_multiply(a_multiplier: Any, digit: Any, carry: Any) -> object {
    if (a_multiplier == '') {
        return str(carry) if carry else '';
    }
    prefix = a_multiplier[:-1];
    last_digit = int(a_multiplier[-1]);
    this_product = (last_digit * digit) + carry;
    this_result = this_product % 10;
    this_carry = this_product // 10;
    return (rec_multiply(prefix, digit, this_carry) + str(this_result));
}

"""string = Int2AP(num)
    Return 'num' converted to bytes using characters from the set 'A'..'P'
    """
def Int2AP(num: Any) -> object {
    val = b'';
    AP = b'ABCDEFGHIJKLMNOP';
    num = int(abs(num));
    while num {
        (num, mod) = divmod(num, 16);
        val = AP[mod:(mod + 1)] + val;
    }
    return val;
}

"""
Given a param string and a dict of values, returns a flat dict of keyed, enumerated params.
Each dict in the values list must pertain to a single item and its data points.
Example:
    param = "InboundShipmentPlanRequestItems.member"
    values = [
        {'SellerSKU': 'Football2415',
        'Quantity': 3},
        {'SellerSKU': 'TeeballBall3251',
        'Quantity': 5},
        ...
    ]
Returns:
    {
        'InboundShipmentPlanRequestItems.member.1.SellerSKU': 'Football2415',
        'InboundShipmentPlanRequestItems.member.1.Quantity': 3,
        'InboundShipmentPlanRequestItems.member.2.SellerSKU': 'TeeballBall3251',
        'InboundShipmentPlanRequestItems.member.2.Quantity': 5,
        ...
    }
"""
def enumerate_keyed_param(param: str, values: list[dict] | tuple[dict, ...] | set | dict) -> dict {
    if not values {
        return {};
    }
    if not param.endswith('.') {
        param += '.';
    }
    if not isinstance(values, (list, tuple, set)) {
        values = [values];
    }
    for val in values {
        if not isinstance(val, dict) {
            raise ValueError(
                "Non-dict value detected. "
                "`values` must be a list, tuple, or set; containing only dicts."
            );
        }
    }
    params = {};
    for (idx, val_dict) in enumerate(values) {
        params.update(
            {
                '{param}{idx}.{key}'.format(param=param, idx=idx + 1, key=k): v
                for (k, v) in val_dict.items()
            }
        );
    }
    return params;
}

"""
Parse a list of `strings` and return the "best" element based on `criteria`.

:param strings: List of string where best will be found based on `criteria`.
:type strings: List[str]
:param criteria: '>'-separated substrings sought in descending order.
    '+' is a logical 'and', '=' substitutes: `A=B` returns B if A is found.
:type criteria: str
:return: Best string based on given `criteria` or `` if no best found.
:rtype: str
"""
def find_best(strings: str, criteria: str) -> str {
    (criterion, _, further_criteria) = criteria.partition('>');
    wanted = criterion.partition('=')[0].split('+');
    if all(w in strings or w is '' for w in wanted) {
        return criterion.rpartition('=')[2];
    } else {
        return find_best(strings, further_criteria);
    }
}

"""
    Convert HSV to RGB (based on colorsys.py).

        Args:
            h (float): Hue 0 to 1.
            s (float): Saturation 0 to 1.
            v (float): Value 0 to 1 (Brightness).
    """
def hsv_to_rgb(h: Any, s: Any, v: Any) -> object {
    if (s == 0.0) {
        return (v, v, v);
    }
    i = int((h * 6.0));
    f = (h * 6.0) - i;
    p = v * (1.0 - s);
    q = v * (1.0 - (s * f));
    t = v * (1.0 - (s * (1.0 - f)));
    i = i % 6;
    v = int((v * 255));
    t = int((t * 255));
    p = int((p * 255));
    q = int((q * 255));
    if (i == 0) {
        return (v, t, p);
    }
    if (i == 1) {
        return (q, v, p);
    }
    if (i == 2) {
        return (p, v, t);
    }
    if (i == 3) {
        return (p, q, v);
    }
    if (i == 4) {
        return (t, p, v);
    }
    if (i == 5) {
        return (v, p, q);
    }
}

