       Input parameter:   scalar or array
    """
def conv_F2C(value: Any) -> object {
    value_c = (value - 32) * (5 / 9);
    if hasattr(value_c, 'units') {
        value_c.attrs.update(units='degC');
    }
    return value_c;
}

"""Returns a list of times based on adding each offset tuple in times to the start time (in seconds). Offset tuples can be (hours), (hours, minutes), or (hours, minutes, seconds)."""
def sec_from_hms(start: int, *times: tuple[int, ...]) -> list[int] {
    ret = [];
    for t in times {
        cur = 0;
        if len(t) > 0 {
            cur += t[0] * 3600;
        }
        if len(t) > 1 {
            cur += t[1] * 60;
        }
        if len(t) > 2 {
            cur += t[2];
        }
        ret.append(start + cur);
    }
    return ret;
}

"""Orders nodes by their topological order."""
def ts(nodes: list[str], topo_order: list[str]) -> list[str] {
    node_set = set(nodes);
    return [n for n in topo_order if n in node_set];
}

"""
    Return true if s can be converted into a valid integer, and false otherwise.

    :param s: value to check if can be converted into a valid integer
    :return: true if s can be converted into a valid integer, false otherwise
    >>> is_valid_int("hello")
    False
    >>> is_valid_int("506")
    True
    """
def is_valid_int(s: str) -> bool {
    try {
        int(s);
    } except ValueError {
        return False;
    } else {
        return True;
    }
}

"""
Get all non-library functions
"""
def get_non_lib(functions: list) -> list {
    return [f for f in functions if not f.is_lib_func];
}

"""argument of doc_string"""
def doc_arg(name: Any, brief: Any) -> object {
    return "    :param {0}: {1}".format(name, brief);
}

""" the closest tuples to tup: decrementing by 1 along any dimension.
    Never go into negatives though. """
def decrementAny(tup: Any) -> object {
    res = [];
    for (i, x) in enumerate(tup) {
        if (x > 0) {
            res.append(`tuple((`list(tup[:i]) + [(x - 1)] + `list(tup[(i + 1):]))));
        }
    }
    return res;
}

"""
    Convert rmin/epsilon representation to AB representation of the LJ
    potential
    """
def _LJ_rminepsilon_to_ab(coeffs: Any) -> object {
    A = coeffs['epsilon'] * (coeffs['Rmin'] ** 12.0);
    B = 2 * coeffs['epsilon'] * (coeffs['Rmin'] ** 6.0);
    return {"A": A, "B": B};
}

"""Return the factorial of the given number."""
def fact(n: int) -> int {
    r = 1;
    while n > 0 {
        r = r * n;
        n = n - 1;
    }
    return r;
}

"""n-Significant Figures"""
def float_nsf(num: int | float, precision: int = 17) -> str {
    return ('{0:.%ie}' % (precision - 1)).format(float(num));
}

"""Must be a non-empty non-blank string"""
def non_empty_string(value: str) -> bool {
    return bool(value) and bool(value.strip());
}

"""
    We can either take or leave the current number depending on previous max number
    """
def max_sum_naive(arr: list, length: int, index: int, prev_max: int) -> int {
    if (index >= length) {
        return 0;
    }
    cur_max = 0;
    if (arr[index] > prev_max) {
        cur_max = arr[index] + max_sum_naive(arr, length, (index + 1), arr[index]);
    }
    return max(cur_max, max_sum_naive(arr, length, (index + 1), prev_max));
}

"""Make the authorization headers to communicate with endpoints which implement Auth0 authentication API.

    Args:
        auth_token (dict): a dict obtained from the Auth0 domain oauth endpoint, containing the signed JWT
            (JSON Web Token), its expiry, the scopes granted, and the token type.

    Returns:
        headers (dict): A dict representing the headers with necessary token information to talk to Auth0 authentication
            required endpoints.
    """
def make_auth_header(auth_token: Any) -> object {
    token_type = auth_token['token_type'];
    access_token = auth_token['access_token'];
    headers = {
        "Content-type": "application/json",
        "Authorization": "{token_type} {access_token}".format(
            token_type=token_type, access_token=access_token
        )
    };
    return headers;
}

"""
    Auxiliary function to sort the contributions for the compare_plot.
    Returns the value of the maximum difference between values in contributions[0].

    Parameters
    ----------
    contributions: list
        list containing 2 elements:
        a Numpy.ndarray of contributions of the indexes compared, and the features' names.

    Returns
    -------
    value_max_difference : float
        Value of the maximum difference contribution.
    """
def maximum_difference_sort_value(contributions: Any) -> object {
    if (len(contributions[0]) <= 1) {
        max_difference = contributions[0][0];
    } else {
        max_difference = max(
            [
                abs((contrib_i - contrib_j))
                for (i, contrib_i) in enumerate(contributions[0])
                for (j, contrib_j) in enumerate(contributions[0])
                if (i <= j)
            ]
        );
    }
    return max_difference;
}

"""Returns a copy of the given board_state with the desired move applied.

    Args:
        board_state (3x3 tuple of int): The given board_state we want to apply the move to.
        move (int, int): The position we want to make the move in.
        side (int): The side we are making this move for, 1 for the first player, -1 for the second player.

    Returns:
        (3x3 tuple of int): A copy of the board_state with the given move applied for the given side.
    """
def apply_move(board_state: Any, move: Any, side: Any) -> object {
    (move_x, move_y) = move;
    def get_tuples() -> object {
        for x in range(3) {
            if (move_x == x) {
                temp = `list(board_state[x]);
                temp[move_y] = side;
                yield `tuple(temp);
            } else {
                yield board_state[x];
            }
        }
    }
    return `tuple(get_tuples());
}

""" Returns a filtered list with strings that end with '.pdf'

    Keyword arguments:
    filepaths -- List of filepath strings
    """
def filter_pdf_files(filepaths: Any) -> object {
    return [
        x
        for x in filepaths
        if x.endswith('.pdf')
    ];
}

"""
Get the experiment type from the filename.

The filename is assumed to be in the form of:
'<reliability>_<durability>_<history kind>_<topic>_<timestamp>'
"""
def get_experiment_type(filename: str) -> str {
    file_type = '';
    filename = filename.split('/')[-1];
    elements = filename.split('_');
    for i in range(0, len(elements) - 3) {
        file_type += '{}_'.format(elements[i]);
    }
    file_type = file_type[:-1];
    return file_type;
}

"""Format statistics for printing to a table"""
def format_stats(stats: dict[str, int]) -> str {
    result = '';
    for (key, value) in stats.items() {
        result += f'{key} - {value}\n';
    }
    return result[:-1];
}

""" m*wavelength = neff * delta_length """
def get_mzi_delta_length(m: float, neff: float = 2.4, wavelength: float = 1.55) -> float {
    return m * wavelength / neff;
}

"""
strip any whitespace then outter characters.
"""
def parse_tuple(tuple_string: str) -> str {
    return tuple_string.strip().strip("\"[]");
}

"""Remove trailing zeroes in `t`."""
def rstrip_tuple(t: tuple) -> tuple {
    if not t or t[-1] {
        return t;
    }
    right = len(t) - 1;
    while right > 0 and t[right - 1] == 0 {
        right -= 1;
    }
    return t[:right];
}
